const app=document.querySelector('#app');
const cities=['Tbilisi','Batumi','Kutaisi','Kazbegi','Telavi','Mestia','Kobuleti'];
const guide={Tbilisi:{intro:'Tbilisi mixes centuries-old balconies, sulfur-bath domes, contemporary galleries, wine bars, and streets made for wandering.',do:'Walk from the Old Town to Narikala, pause in the Abanotubani bath district, then follow the river toward Dry Bridge and the cafés around Fabrika.'},Batumi:{intro:'Batumi is Georgia’s Black Sea escape: a long seafront promenade, palm-lined evenings, modern architecture, and a green hinterland.',do:'Start on the Boulevard, visit the Botanical Garden, take in the old streets near Europe Square, and leave time for a sunset by the water.'},Kutaisi:{intro:'Kutaisi is a relaxed western-Georgian base with historic monasteries, fresh markets, limestone caves, and canyon day trips.',do:'See Bagrati Cathedral and Gelati Monastery, then plan a trip to Prometheus Cave, Okatse Canyon, or Martvili Canyon.'},Kazbegi:{intro:'Kazbegi is high-mountain Georgia: dramatic valleys, crisp air, hiking routes, and the iconic Gergeti Trinity Church.',do:'Drive or hike to Gergeti, explore the Dariali Gorge, and book enough time for weather changes and slow mountain views.'},Telavi:{intro:'Telavi sits in Kakheti wine country, between vineyards, family cellars, market stalls, and views toward the Caucasus.',do:'Taste local wines at a family cellar, visit the Batonistsikhe fortress, and take a day trip through the Alazani Valley.'},Mestia:{intro:'Mestia is the heart of Svaneti, known for medieval towers, alpine trails, local food, and an unforgettable mountain setting.',do:'Visit the Svan towers and museum, walk the village paths, and use Mestia as a base for mountain walks or a trip to Ushguli.'},Kobuleti:{intro:'Kobuleti is a calmer Black Sea town for slow beach days, cafés, and easy access to Adjara’s green landscapes.',do:'Spend time by the beach, try local Adjarian dishes, and take a short trip to nearby nature areas when you want a break from the coast.'}};
const cityStories={Tbilisi:{history:'Tbilisi grew around warm sulfur springs on the banks of the Mtkvari River, and its name is linked to the Georgian word for warm. Over centuries it became a meeting point between Europe and Asia, shaped by Georgian, Persian, Armenian, Russian, and Silk Road influences. The old town still tells that story through carved wooden balconies, brick bath domes, churches, mosques, courtyards, and winding lanes.',experience:'Spend the morning in Abanotubani, climb toward Narikala Fortress for wide city views, and cross the river to browse the Dry Bridge market. In the evening, explore Sololaki or Vera for galleries, wine bars, and modern Georgian food. Tbilisi is compact enough for spontaneous walks, but every neighborhood has a different rhythm.'},Batumi:{history:'Batumi has long been a Black Sea port and a gateway between Georgia and the wider region. Its nineteenth-century boulevards, subtropical climate, and maritime location gave the city a distinct personality. Today historic façades sit beside ambitious contemporary buildings, creating a city that feels both resort-like and urban.',experience:'Walk the long seaside Boulevard, linger around Europe Square and the Old Town, then visit the Batumi Botanical Garden on the green coastline north of the city. Cafés come alive after sunset, while the beach and waterfront make space for a slower afternoon. Batumi also works well as a base for discovering the forests and villages of Adjara.'},Kutaisi:{history:'Kutaisi is one of Georgia’s oldest cities and the historic heart of the Imereti region. It is associated with the ancient kingdom of Colchis and later became an important royal centre. Bagrati Cathedral and Gelati Monastery, both tied to Georgia’s medieval cultural history, are among the city’s most significant landmarks.',experience:'Begin at Bagrati Cathedral for a view across the city, then visit Gelati’s frescoes and peaceful grounds. Kutaisi is also the perfect starting point for western Georgia’s natural wonders: Prometheus Cave, Martvili Canyon, Okatse Canyon, and the green valleys around Imereti. Finish with a stroll through the market and a simple local meal.'},Kazbegi:{history:'Kazbegi, now officially called Stepantsminda, lies on the old Georgian Military Highway close to the Russian border. The landscape has always made it a strategic mountain passage and a place of legends. Its most famous image is Gergeti Trinity Church, standing high above the town beneath the dramatic slopes of Mount Kazbek.',experience:'Wake early for clear views of Gergeti and take a hike or drive to the church. Continue into the Dariali Gorge, look for waterfalls and trails, and leave extra time for weather changes. Mountain cafés, khinkali, and quiet evenings make Kazbegi feel very different from Georgia’s larger cities.'},Telavi:{history:'Telavi is the cultural centre of Kakheti, Georgia’s eastern wine region. The town has royal history, old stone lanes, markets, and a landscape of vineyards stretching toward the Caucasus. Its fortress, Batonistsikhe, recalls the era of King Erekle II and the independent kingdom of Kakheti.',experience:'Visit the fortress and local market before heading out to small wineries and family cellars in the Alazani Valley. Taste qvevri wine, try Kakhetian food, and plan a scenic drive toward Sighnaghi, Tsinandali, or Gremi. Telavi is best enjoyed slowly, with time for long lunches and conversations.'},Mestia:{history:'Mestia is the main town of Svaneti, a remote highland region with a powerful cultural identity. The area is famous for its defensive stone towers, built by Svan families over many centuries, and for traditions preserved by mountain isolation. Its architecture and landscape make it one of Georgia’s most memorable destinations.',experience:'Explore the towers and museum in town, then choose a gentle village walk or a longer alpine route. Mestia is a gateway to Ushguli, one of Europe’s highest inhabited villages, and to winter skiing at Tetnuldi. Local Svan dishes, mountain hospitality, and a slower pace are as memorable as the scenery.'},Kobuleti:{history:'Kobuleti is a coastal town in Adjara, north of Batumi, with a long tradition as a Black Sea holiday destination. Its wide pebble beach and subtropical surroundings made it popular for summer escapes, while the nearby wetlands and forested areas reveal a quieter side of the coast.',experience:'Take relaxed walks along the shore, visit the cafés and small markets, and spend a day at Kobuleti Protected Areas if you enjoy birdlife and wetland scenery. The town is ideal for travellers who want beach time without the scale and nightlife of Batumi, while still being close enough for an easy day trip.'}};
const translatedGuide={ru:{intro:'Откройте для себя историю, культуру, кухню и лучшие маршруты этого грузинского направления.',history:'Этот город занимает важное место в истории и культуре Грузии. Его старые улицы, архитектура, местные традиции и природное окружение помогают почувствовать характер региона. Здесь прошлое не отделено от повседневной жизни: исторические места, рынки, семейные кафе и живые кварталы находятся рядом друг с другом.',experience:'Начните знакомство с исторического центра, попробуйте региональную кухню и оставьте время для прогулок без спешки. Спросите у хозяина жилья о местных маршрутах, транспорте и местах, которые особенно красивы утром или на закате.'},ka:{intro:'აღმოაჩინეთ ამ ქართული მიმართულების ისტორია, კულტურა, სამზარეულო და საუკეთესო მარშრუტები.',history:'ეს ქალაქი საქართველოს ისტორიასა და კულტურაში მნიშვნელოვან ადგილს იკავებს. მისი ძველი ქუჩები, არქიტექტურა, ადგილობრივი ტრადიციები და ბუნებრივი გარემო რეგიონის ხასიათს წარმოაჩენს. აქ წარსული ყოველდღიურ ცხოვრებასთან ახლოსაა — ისტორიული ადგილები, ბაზრები, საოჯახო კაფეები და ცოცხალი უბნები ერთმანეთის გვერდით მდებარეობს.',experience:'დაიწყეთ ისტორიული ცენტრით, დააგემოვნეთ რეგიონის სამზარეულო და დრო დაუთმეთ მშვიდ სეირნობას. ჰკითხეთ მასპინძელს ადგილობრივი მარშრუტების, ტრანსპორტისა და იმ ადგილების შესახებ, რომლებიც დილით ან მზის ჩასვლისას განსაკუთრებით ლამაზია.'}};
function guideFor(name){if(language==='en')return {...guide[name],...cityStories[name]};return translatedGuide[language]}
