function localize(){document.documentElement.lang=language;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(n=>{const clean=n.nodeValue.trim();if(clean&&words[language]?.[clean])n.nodeValue=n.nodeValue.replace(clean,translate(clean));if(language==='ru'){n.nodeValue=n.nodeValue.replace('Your stay at ','Ваше проживание в ').replace('Georgia','Грузия').replace(/(\d+) nights?/g,'$1 ночей').replace(/(\d+) guests?/g,'$1 гостей')}if(language==='ka'){n.nodeValue=n.nodeValue.replace('Your stay at ','თქვენი დასვენება: ').replace('Georgia','საქართველო').replace(/(\d+) nights?/g,'$1 ღამე').replace(/(\d+) guests?/g,'$1 სტუმარი')}});document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(x=>{const p=x.getAttribute('placeholder');if(words[language]?.[p])x.setAttribute('placeholder',translate(p))})}
