function localize(){document.documentElement.lang=language;const dictionary=words[language]||{};const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(n=>{let value=n.nodeValue;Object.entries(dictionary).forEach(([en,local])=>{if(en!==local&&value.includes(en))value=value.split(en).join(local)});n.nodeValue=value});document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(x=>{const p=x.getAttribute('placeholder');if(dictionary[p])x.setAttribute('placeholder',dictionary[p])})}
Object.assign(words.ru,{'seats':'мест','bags':'багажа','Air conditioning':'Кондиционер','Unlimited kilometres':'Неограниченный пробег','No cars are free for those dates. Try different dates.':'На эти даты свободных автомобилей нет. Попробуйте другие даты.','Drop-off must be after pick-up.':'Дата возврата должна быть позже даты получения.','Rental price':'Стоимость аренды','Taxes (18%)':'Налоги (18%)','Pay at pick-up. Bring your driving licence and confirmation email.':'Оплата при получении. Возьмите водительское удостоверение и письмо-подтверждение.'});Object.assign(words.ka,{'seats':'ადგილი','bags':'ბარგი','Air conditioning':'კონდიციონერი','Unlimited kilometres':'შეუზღუდავი გარბენი','No cars are free for those dates. Try different dates.':'ამ თარიღებში თავისუფალი მანქანა არ არის. სცადეთ სხვა თარიღები.','Drop-off must be after pick-up.':'დაბრუნების თარიღი აღების თარიღზე გვიანი უნდა იყოს.','Rental price':'ქირაობის ფასი','Taxes (18%)':'გადასახადები (18%)','Pay at pick-up. Bring your driving licence and confirmation email.':'გადახდა მიღებისას. თან იქონიეთ მართვის მოწმობა და დასტურის ელფოსტა.'});
const baseLocalize=localize;localize=()=>{baseLocalize();const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(n=>{if(language==='ru')n.nodeValue=n.nodeValue.replaceAll('Georgia','Грузия').replace(/(\d+) nights?/g,'$1 ночей').replace(/(\d+) guests?/g,'$1 гостей');if(language==='ka')n.nodeValue=n.nodeValue.replaceAll('Georgia','საქართველო').replace(/(\d+) nights?/g,'$1 ღამე').replace(/(\d+) guests?/g,'$1 სტუმარი')})};
const translationObserver=new MutationObserver(()=>{clearTimeout(window.__vacayTranslationTimer);window.__vacayTranslationTimer=setTimeout(localize,0)});translationObserver.observe(app,{childList:true,subtree:true});
function addControls(){const header=document.querySelector('header');header.insertAdjacentHTML('beforeend','<div class="site-tools"><select id="language-select" aria-label="Language"><option value="en">EN</option><option value="ka">ქარ</option><option value="ru">РУ</option></select><button id="theme-toggle" aria-label="Dark mode">◐</button></div>');const select=document.querySelector('#language-select');select.value=language;select.onchange=()=>{localStorage.setItem('vacayLanguage',select.value);location.reload()};const toggle=document.querySelector('#theme-toggle');const dark=localStorage.getItem('vacayTheme')==='dark';document.body.classList.toggle('dark',dark);toggle.onclick=()=>{const on=document.body.classList.toggle('dark');localStorage.setItem('vacayTheme',on?'dark':'light')}}
const api=async(url,options={})=>{const token=localStorage.getItem('vacayToken');const r=await fetch(url,{...options,headers:{...(options.headers||{}),...(token?{Authorization:`Bearer ${token}`}:{})}});let b={};try{b=await r.json()}catch{}if(!r.ok){if(url==='/api/car-rentals/mine'&&(r.status===401||r.status===403||r.status===404||r.status>=500))return[];const error=new Error(b.message||'Something went wrong. Please try again.');error.status=r.status;throw error}return b.data};
const optionalApi=async(url,fallback)=>{try{return await api(url)}catch{return fallback}};
function signedInEmail(){try{const token=localStorage.getItem('vacayToken'),payload=JSON.parse(atob(token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));return payload.email||payload['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress']||sessionStorage.getItem('vacayEmail')||''}catch{return sessionStorage.getItem('vacayEmail')||''}}
const savedEmail=signedInEmail();if(savedEmail)sessionStorage.setItem('vacayEmail',savedEmail);
async function refreshAccount(){const area=document.querySelector('#account-area');if(!localStorage.getItem('vacayToken')){area.innerHTML='<button data-page="login">Log in</button><button class="primary" data-page="signup">Sign up</button>';links();return}const showAccount=name=>{area.innerHTML=`<button data-page="profile">${name||localStorage.getItem('vacayName')||'My profile'}</button><button id="logout">Log out</button>`;links();document.querySelector('#logout').onclick=()=>{localStorage.removeItem('vacayToken');localStorage.removeItem('vacayName');location.hash='home';refreshAccount()}};try{const guest=await api('/api/guests/me');localStorage.setItem('vacayName',guest.firstName);showAccount(guest.firstName)}catch{showAccount()}}
const cityOptions=s=>cities.map(c=>`<option ${c===s?'selected':''}>${c}</option>`).join('');
const guestOptions=s=>Array.from({length:10},(_,i)=>`<option value="${i+1}" ${i+1===+(s||2)?'selected':''}>${i+1} guest${i?'s':''}</option>`).join('');
function links(){document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>location.hash=x.dataset.page)}
function searchForm(s=getSearch()||{}){return `<form class="search" id="search"><h2>Find your stay</h2><div class="fields"><div><label>Destination</label><select name="city">${cityOptions(s.city||'Tbilisi')}</select></div><div><label>Guests</label><select name="guests">${guestOptions(s.guests)}</select></div><div><label>Check in</label><input type="date" name="checkIn" min="${today()}" value="${s.checkIn||''}" required></div><div><label>Check out</label><input type="date" name="checkOut" min="${today()}" value="${s.checkOut||''}" required></div></div><button class="primary">Search availability</button></form>`}
function bindSearch(){const form=document.querySelector('#search');if(form)form.onsubmit=e=>{e.preventDefault();const s=Object.fromEntries(new FormData(form));if(s.checkOut<=s.checkIn)return alert('Check-out must be after check-in.');putSearch(s);location.hash='stays'}}
function home(){app.innerHTML=`<section class="hero"><div><p class="tag">Georgia, beautifully local</p><h1>Book a stay worth remembering.</h1><p>Search hotels across Georgia, compare room details, and reserve your next escape with Vacay.</p><button class="primary" data-page="guides">Explore city guides</button></div>${searchForm()}</section><section class="cities">${cities.map(c=>`<button data-city="${c}">${c}</button>`).join('')}</section><section class="section"><p class="tag">City guides</p><div class="topline"><h2>More than a place to sleep</h2><button data-page="guides">All guides</button></div><div class="cards">${cities.slice(0,3).map(cityCard).join('')}</div></section>`;links();bindSearch();document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>location.hash='city/'+b.dataset.city)}
function cityCard(c){const g=guideFor(c);return `<article class="city" style="background-image:linear-gradient(#0001,#211625bd),url('${photoUrl(c,1100)}')"><small>${language==='ka'?'აღმოაჩინე საქართველო':language==='ru'?'Откройте Грузию':'Discover Georgia'}</small><h3>${c}</h3><p>${g.intro}</p><button data-city="${c}">Read guide</button></article>`}
function guides(){app.innerHTML=`<section class="page"><p class="tag">Seven places to know</p><h1>City guides</h1><p class="lead">Build a trip around food, nature, old streets, sea air, and the small moments between them.</p><div class="cards">${cities.map(cityCard).join('')}</div></section>`;document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>location.hash='city/'+b.dataset.city)}
function city(name){const g=guideFor(name);app.innerHTML=`<section class="guide-hero" style="background-image:linear-gradient(#21162555,#211625bd),url('${photoUrl(name,1800)}')"><p class="tag">Vacay guide · Georgia</p><h1>${name}</h1><p>${g.intro}</p></section><section class="page"><div class="guide-grid"><section class="guide"><h2>History and character</h2><p>${g.history}</p><h2>What to do</h2><p>${g.experience}</p><h3>Good to know</h3><p>${language==='ka'?'დაგეგმეთ დღე მოქნილად, განსაკუთრებით მთიან რეგიონებში. მასპინძელს ჰკითხეთ ტრანსპორტის, სამუშაო საათებისა და ადგილობრივი რეკომენდაციების შესახებ.':language==='ru'?'Сохраняйте гибкость в планах, особенно в горных районах. Спросите у хозяина жилья о транспорте, времени работы и местных рекомендациях.':'Keep your itinerary flexible, especially in the mountains. Ask your accommodation about transport, opening hours, and local recommendations.'}</p></section><aside class="guide"><h2>Find a stay</h2><p>${language==='ka'?'აირჩიეთ თარიღები ერთხელ და გაჩვენებთ თქვენს მოგზაურობასთან შესაბამის ნომრებს.':language==='ru'?'Выберите даты один раз — и мы покажем номера, подходящие для вашей поездки.':'Choose dates once and we will show rooms that match your trip.'}</p>${searchForm({...getSearch(),city:name})}</aside></div></section>`;bindSearch()}
function city(name){const g=guideFor(name),extra=language==='en'?`<p>Travelling through ${name} is best approached slowly. Give yourself time to notice how daily life, food, landscapes, and history connect. Start with the central streets and landmarks, then move beyond the obvious route: ask a local café owner, your host, or a market vendor for a favourite walk, viewpoint, or family restaurant.</p><p>For a more comfortable visit, keep your days flexible and build in pauses. Georgia’s hospitality is often spontaneous: a conversation can turn into a recommendation, a small winery visit, or a memorable meal. Public transport and opening hours can vary, so confirm practical details locally and leave room for unexpected discoveries.</p><p>Vacay recommends choosing a stay close to the experiences you value most. Select dates once, compare room details and breakfast options, and use your host message area after booking for arrival advice, local transport suggestions, and neighbourhood recommendations.</p>`:language==='ru'?`<p>Знакомиться с ${name} лучше без спешки. Оставьте время, чтобы увидеть связь повседневной жизни, кухни, природы и истории. Начните с центральных улиц и главных мест, а затем выйдите за пределы обычного маршрута: спросите у хозяина жилья, владельца кафе или продавца на рынке о любимой прогулке, смотровой площадке или семейном ресторане.</p><p>Для комфортной поездки сохраняйте гибкость в планах. В Грузии разговор часто превращается в рекомендацию, визит на небольшую винодельню или запоминающийся ужин. Транспорт и время работы могут меняться, поэтому уточняйте детали на месте и оставляйте пространство для неожиданных открытий.</p><p>Vacay советует выбрать жильё рядом с теми впечатлениями, которые для вас важнее всего. Выберите даты один раз, сравните номера и варианты завтрака, а после бронирования используйте сообщение хозяину для советов по приезду и району.</p>`:`<p>${name} საუკეთესოდ მშვიდად გასაცნობი ადგილია. დრო დაუთმეთ იმას, რომ ყოველდღიური ცხოვრება, სამზარეულო, ბუნება და ისტორია ერთად დაინახოთ. დაიწყეთ ცენტრალური ქუჩებითა და ღირსშესანიშნაობებით, შემდეგ კი ჩვეულებრივ მარშრუტს გასცდით — ჰკითხეთ მასპინძელს, კაფის მფლობელს ან ბაზრის გამყიდველს საყვარელი სეირნობის, ხედის ან საოჯახო რესტორნის შესახებ.</p><p>კომფორტული მოგზაურობისთვის გეგმა მოქნილი დატოვეთ. საქართველოში საუბარი ხშირად კარგ რეკომენდაციად, პატარა მარანში სტუმრობად ან დასამახსოვრებელ ვახშმად იქცევა. ტრანსპორტი და სამუშაო საათები შეიძლება შეიცვალოს, ამიტომ დეტალები ადგილზე გადაამოწმეთ და მოულოდნელი აღმოჩენებისთვის დროც დაიტოვეთ.</p><p>Vacay გირჩევთ, აირჩიოთ საცხოვრებელი იმ გამოცდილებებთან ახლოს, რომლებიც თქვენთვის ყველაზე მნიშვნელოვანია. თარიღები ერთხელ აირჩიეთ, შეადარეთ ნომრები და საუზმის ვარიანტები, ხოლო დაჯავშნის შემდეგ მასპინძელს მისწერეთ ჩასვლისა და უბნის რჩევებისთვის.</p>`;app.innerHTML=`<section class="guide-hero" style="background-image:linear-gradient(#21162555,#211625bd),url('${photoUrl(name,1800)}')"><p class="tag">Vacay guide · Georgia</p><h1>${name}</h1><p>${g.intro}</p></section><section class="page"><div class="guide-grid"><section class="guide"><h2>History and character</h2><p>${g.history}</p><h2>What to do</h2><p>${g.experience}</p>${extra}<h3>Good to know</h3><p>${language==='ka'?'დაგეგმეთ დღე მოქნილად, განსაკუთრებით მთიან რეგიონებში. მასპინძელს ჰკითხეთ ტრანსპორტის, სამუშაო საათებისა და ადგილობრივი რეკომენდაციების შესახებ.':language==='ru'?'Сохраняйте гибкость в планах, особенно в горных районах. Спросите у хозяина жилья о транспорте, времени работы и местных рекомендациях.':'Keep your itinerary flexible, especially in the mountains. Ask your accommodation about transport, opening hours, and local recommendations.'}</p></section><aside class="guide"><h2>Find a stay</h2><p>${language==='ka'?'აირჩიეთ თარიღები ერთხელ და გაჩვენებთ თქვენს მოგზაურობასთან შესაბამის ნომრებს.':language==='ru'?'Выберите даты один раз — и мы покажем номера, подходящие для вашей поездки.':'Choose dates once and we will show rooms that match your trip.'}</p>${searchForm({...getSearch(),city:name})}</aside></div></section>`;bindSearch()}
async function stays(){const s=getSearch();if(!s){location.hash='home';return}app.innerHTML=`<section class="page results-page"><p class="tag">Your search</p><h2>${s.city} · ${s.guests} guests</h2><p>${s.checkIn} → ${s.checkOut}</p><button id="change-search">Change search</button><div id="results" class="results"><p>Loading hotels and rooms…</p></div></section>`;document.querySelector('#change-search').onclick=()=>location.hash='home';try{const hotels=await api('/api/hotels?city='+encodeURIComponent(s.city));const details=await Promise.all(hotels.map(async h=>({h,rooms:(await api(`/api/hotels/${h.id}/rooms?checkIn=${s.checkIn}&checkOut=${s.checkOut}`)).filter(r=>r.capacity>=+s.guests)})));const available=details.filter(x=>x.rooms.length);document.querySelector('#results').innerHTML=available.length?`<div class="hotel-list">${available.map(({h,rooms},i)=>hotelCard(h,rooms[0],i)).join('')}</div>`:'<div class="notice">No rooms fit this search yet. Try fewer guests or different dates.</div>';document.querySelectorAll('[data-hotel]').forEach(b=>b.onclick=()=>location.hash='hotel/'+b.dataset.hotel)}catch(e){document.querySelector('#results').innerHTML=`<div class="error">${e.message}</div>`}}
function hotelCard(h,r,i){return `<article class="hotel-card"><img src="${roomPhoto(i)}" alt="Hotel room"><div><p class="tag">${h.city} · ${'★'.repeat(h.rating)}</p><h2>${h.name}</h2><p>${h.address}</p><p><strong>${r.name}</strong> · Up to ${r.capacity} guests${r.breakfastIncluded?' · Breakfast included':''}</p></div><aside><small>From</small><strong>$${r.price}</strong><small>per night</small><button class="primary" data-hotel="${h.id}">View rooms</button></aside></article>`}
function guestVoices(id){const host=demoHosts[id%demoHosts.length];return `<section class="hotel-extra"><div class="host-card"><img src="https://images.unsplash.com/${host.photo}?auto=format&fit=crop&w=240&q=80" alt="${host.name}"><div><p class="tag">Meet your host</p><h3>${host.name}</h3><p>${host.role}</p><p>I can help with check-in questions and ideas for your stay.</p></div></div><div><p class="tag">Guest reviews</p><h2>What guests liked</h2><div class="review-list">${reviewText.map((text,i)=>`<article class="review"><strong>${['Mariam','Sandro','Elisa'][i]}</strong><span> · ${9-i/2}/10</span><p>“${text}”</p></article>`).join('')}</div></div></section>`}
async function hotel(id){const s=getSearch();app.innerHTML='<section class="page"><p>Loading hotel and available rooms…</p></section>';try{const h=await api('/api/hotels/'+id),qs=s?`?checkIn=${s.checkIn}&checkOut=${s.checkOut}`:'';const rooms=(await api('/api/hotels/'+id+'/rooms'+qs)).filter(r=>!s||r.capacity>=+s.guests);app.innerHTML=`<section class="hotel-hero" style="background-image:linear-gradient(#21162544,#211625c9),url('${roomPhoto(+id)}')"><p class="tag">${h.city} · ${'★'.repeat(h.rating)}</p><h1>${h.name}</h1><p>${h.address}, Georgia</p></section><section class="page"><div class="booking-bar">${s?`${s.checkIn} → ${s.checkOut} · ${s.guests} guests`:'Choose dates to check availability'} <button data-page="home">Change</button></div><div class="hotel-actions"><button id="save-favorite">♡ Save to favourites</button></div><h2>Available rooms</h2><div class="room-list">${rooms.length?rooms.map((r,i)=>roomCard(r,i,!!s)).join(''):'<div class="notice">No suitable rooms are available for these dates and guest count.</div>'}</div>${guestVoices(+id)}</section>`;links();document.querySelectorAll('[data-book-room]').forEach(b=>b.onclick=()=>bookRoom(id,b.dataset.bookRoom));document.querySelector('#save-favorite').onclick=async()=>{if(!localStorage.getItem('vacayToken')){location.hash='login';return}try{await api('/api/favorites/'+id,{method:'POST'});document.querySelector('#save-favorite').textContent='♥ Saved to favourites'}catch(e){alert(e.message)}}}catch(e){app.innerHTML=`<section class="page"><h2>We could not load this hotel.</h2><p>${e.message}</p><button data-page="stays">Back to results</button></section>`;links()}}
function roomCard(r,i,ready){return `<article class="room-card"><img src="${roomPhoto(i)}" alt="${r.name}"><div><h3>${r.name}</h3><p>Up to ${r.capacity} guest${r.capacity===1?'':'s'} · ${r.sizeSquareMeters} m²</p><p>${r.breakfastIncluded?'Breakfast included':'Room only — breakfast not included'}</p></div><aside><strong>$${r.price}</strong><small>per night</small><button class="primary" data-book-room="${r.id}">${ready?'Reserve':'Select dates'}</button></aside></article>`}
function bookRoom(hotelId,roomId){const s=getSearch();if(!s){location.hash='home';return}sessionStorage.setItem('vacayPendingBooking',JSON.stringify({hotelId,roomId}));location.hash=localStorage.getItem('vacayToken')?'checkout':'login'}
async function checkout(){const s=getSearch(),pending=JSON.parse(sessionStorage.getItem('vacayPendingBooking')||'null');if(!s||!pending){location.hash='home';return}if(!localStorage.getItem('vacayToken')){location.hash='login';return}app.innerHTML='<section class="page"><p>Preparing your reservation…</p></section>';try{const [guest,hotel,rooms]=await Promise.all([api('/api/guests/me'),api('/api/hotels/'+pending.hotelId),api('/api/hotels/'+pending.hotelId+'/rooms?checkIn='+s.checkIn+'&checkOut='+s.checkOut)]);const room=rooms.find(x=>x.id===+pending.roomId);if(!room)throw new Error('This room is no longer available. Please choose another room.');const nights=Math.max(1,(new Date(s.checkOut)-new Date(s.checkIn))/86400000),base=room.price*nights,tax=Math.round(base*.18*100)/100,total=base+tax;app.innerHTML=`<section class="page checkout"><p class="tag">Complete reservation</p><h2>Your stay at ${hotel.name}</h2><div class="checkout-grid"><section class="form-card"><h3>Guest details</h3><label>Full name</label><input value="${guest.firstName} ${guest.lastName}" disabled><label>Email</label><input value="${sessionStorage.getItem('vacayEmail')||''}" disabled><label>Phone number</label><input value="${guest.phoneNumber}" disabled><label>How many guests are staying?</label><select id="booking-guests">${Array.from({length:room.capacity},(_,i)=>`<option ${i+1===+s.guests?'selected':''}>${i+1} guest${i?'s':''}</option>`).join('')}</select><label>Special request (optional)</label><textarea placeholder="For example: late check-in"></textarea><p class="tiny">You can update your personal details from your profile.</p><button class="primary" id="confirm-reservation">Confirm reservation</button></section><aside class="price-card"><p class="tag">Reservation summary</p><h3>${room.name}</h3><p>${hotel.city}, Georgia</p><p>${s.checkIn} → ${s.checkOut}<br>${nights} night${nights===1?'':'s'}</p><hr><p>Room price <strong>$${base.toFixed(2)}</strong></p><p>Taxes and fees (18%) <strong>$${tax.toFixed(2)}</strong></p><h3>Total $${total.toFixed(2)}</h3><div class="pay-property">Pay at the property<br><small>No payment is taken online.</small></div></aside></div></section>`;document.querySelector('#confirm-reservation').onclick=async()=>{const b=document.querySelector('#confirm-reservation');b.disabled=true;b.textContent='Making reservation…';try{const reservation=await api(`/api/hotels/${pending.hotelId}/reservations`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({checkInDate:s.checkIn,checkOutDate:s.checkOut,roomIds:[+pending.roomId]})});sessionStorage.removeItem('vacayPendingBooking');app.innerHTML=`<section class="page narrow confirmation"><p class="tag">Reservation confirmed</p><h2>Your trip is booked!</h2><p class="confirmation-icon">✦</p><p>Reservation #${reservation.id} is confirmed for <strong>${hotel.name}</strong>, ${hotel.city}.</p><div class="guide"><p><strong>${s.checkIn}</strong> → <strong>${s.checkOut}</strong></p><p>${room.name} · ${s.guests} guest${+s.guests===1?'':'s'} · Pay at property</p><p>A confirmation email with your stay details and host information was sent to your email.</p></div><button class="primary" data-page="profile">See my trips</button></section>`;links()}catch(e){b.disabled=false;b.textContent='Confirm reservation';alert(e.message)}}}catch(e){app.innerHTML=`<section class="page"><h2>We could not prepare your reservation.</h2><p>${e.message}</p><button data-page="stays">Back to results</button></section>`;links()}}
function about(){const content=language==='ru'?{tag:'О Vacay',title:'Путешествуйте более лично.',plan:'Планируйте уверенно',planText:'Vacay позволяет сравнить доступные номера, вместимость, варианты завтрака, цены и информацию о городе перед бронированием.',made:'Создано для Грузии',madeText:'От старых улиц Тбилиси до горных троп Сванетии — мы выбираем варианты проживания, которые помогают лучше узнать каждое направление.',contact:'Связаться с Vacay',help:'Чтобы выбрать город или номер, воспользуйтесь помощником Vacay на любой странице.'}:language==='ka'?{tag:'Vacay-ს შესახებ',title:'იმოგზაურე უფრო პირადად.',plan:'დაგეგმე თავდაჯერებულად',planText:'Vacay გაძლევს შესაძლებლობას დაჯავშნამდე შეადარო ხელმისაწვდომი ნომრები, სტუმრების რაოდენობა, საუზმის ვარიანტები, ფასები და ინფორმაცია ქალაქის შესახებ.',made:'შექმნილია საქართველოსთვის',madeText:'თბილისის ძველი ქუჩებიდან სვანეთის მთის ბილიკებამდე, ჩვენ ვარჩევთ საცხოვრებლებს, რომლებიც თითოეული მიმართულების უკეთ გაცნობაში დაგეხმარება.',contact:'დაუკავშირდი Vacay-ს',help:'ქალაქის ან ნომრის არჩევაში დახმარებისთვის გამოიყენე Vacay-ს ასისტენტი ნებისმიერ გვერდზე.'}:{tag:'About Vacay',title:'Travel in a more personal way.',plan:'Plan with confidence',planText:'Vacay lets you compare available rooms, guest capacity, breakfast options, prices, and city information before you reserve.',made:'Made for Georgia',madeText:'From Tbilisi’s old streets to Svaneti’s mountain paths, we focus on stays that help you get more from each destination.',contact:'Contact Vacay',help:'For help choosing a city or a room, use the Vacay assistant on any page.'};app.innerHTML=`<section class="page"><p class="tag">${content.tag}</p><h1>${content.title}</h1><div class="guide-grid"><section class="guide"><h2>${content.plan}</h2><p>${content.planText}</p><h2>${content.made}</h2><p>${content.madeText}</p></section><section class="guide"><h2>${content.contact}</h2><p>24 Rustaveli Avenue, Tbilisi, Georgia</p><p>hello@vacay.ge<br>+995 32 2 555 404</p><p>${content.help}</p></section></div></section>`}
function formError(e){const x=document.querySelector('#message');if(x)x.innerHTML=`<div class="error">${e.message}</div>`}
function signup(){app.innerHTML=`<section class="page narrow"><p class="tag">Join Vacay</p><h2>Create your account</h2><form class="form-card" id="signup"><label>First name</label><input name="firstName" required><label>Last name</label><input name="lastName" required><label>Personal number</label><input name="personalNumber" inputmode="numeric" required><label>Phone number</label><input name="phoneNumber" type="tel" required><label>Email</label><input type="email" name="email" required><label>Password</label><input type="password" name="password" minlength="6" required><button class="primary">Create account</button><div id="message"></div></form><p>Already registered? <a href="#login"><u>Log in</u></a></p></section>`;document.querySelector('#signup').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));try{await api('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)});sessionStorage.setItem('vacayEmail',v.email);location.hash='confirm-email'}catch(err){formError(err)}}}
function login(){app.innerHTML=`<section class="page narrow"><p class="tag">Welcome back</p><h2>Log in securely</h2><p>Enter your password, then we will send a one-time code to your verified email.</p><form class="form-card" id="login"><label>Email</label><input type="email" name="email" value="${sessionStorage.getItem('vacayEmail')||''}" required><label>Password</label><input type="password" name="password" required><button class="primary">Send login code</button><div id="message"></div></form><p>New here? <a href="#signup"><u>Create an account</u></a></p></section>`;document.querySelector('#login').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));try{await api('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)});sessionStorage.setItem('vacayEmail',v.email);location.hash='confirm-login'}catch(err){formError(err)}}}
function confirm(kind){if(kind!=='email'){location.hash='login';return}const email=sessionStorage.getItem('vacayEmail')||'',isEmail=true;app.innerHTML=`<section class="page narrow"><p class="tag">Secure verification</p><h2>Confirm your email</h2><p>We sent a six-digit code to your email address. It expires in 10 minutes.</p><form class="form-card" id="confirm"><label>Email</label><input type="email" name="email" value="${email}" required><label>Six-digit code</label><input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required><button class="primary">Confirm</button><div id="message"></div></form><button id="resend-code">Resend verification code</button></section>`;document.querySelector('#confirm').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));try{await api('/api/auth/confirm-email',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)});document.querySelector('#message').innerHTML='<div class="notice">Email confirmed. Redirecting to log in…</div>';setTimeout(()=>location.hash='login',700)}catch(err){formError(err)}};document.querySelector('#resend-code').onclick=async()=>{const address=document.querySelector('#confirm [name=email]').value;try{await api('/api/auth/resend-confirmation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:address,code:''})});document.querySelector('#message').innerHTML='<div class="notice">New code sent. Check Inbox and Spam.</div>'}catch(err){formError(err)}}}
async function profile(){if(!localStorage.getItem('vacayToken')){location.hash='login';return}app.innerHTML='<section class="page"><p>Loading your traveller profile…</p></section>';try{const [guest,reservations,favorites]=await Promise.all([api('/api/guests/me'),api('/api/reservations'),api('/api/favorites')]);app.innerHTML=`<section class="page"><p class="tag">Your Vacay account</p><h2>Hi, ${guest.firstName}</h2><div class="profile-tabs"><button data-panel="details">Profile details</button><button data-panel="trips">My trips (${reservations.length})</button><button data-panel="favorites">Saved places (${favorites.length})</button></div><div id="profile-panel"></div></section>`;const panel=document.querySelector('#profile-panel');const details=()=>{panel.innerHTML=`<form class="form-card profile-form" id="profile-form"><h3>Your details</h3><label>First name</label><input name="firstName" value="${guest.firstName}" required><label>Last name</label><input name="lastName" value="${guest.lastName}" required><label>Personal number</label><input name="personalNumber" value="${guest.personalNumber}" required><label>Phone number</label><input name="phoneNumber" value="${guest.phoneNumber}" required><button class="primary">Save changes</button><div id="message"></div></form>`;document.querySelector('#profile-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/guests/me',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});document.querySelector('#message').innerHTML='<div class="notice">Your details were saved.</div>';refreshAccount()}catch(err){formError(err)}}};const trips=()=>{panel.innerHTML=reservations.length?`<div class="trip-list">${reservations.map(r=>`<article class="guide"><h3>${r.checkInDate} → ${r.checkOutDate}</h3><p>${r.reservationRooms.map(x=>x.room.name).join(', ')}</p><p>Reservation #${r.id}</p></article>`).join('')}</div>`:'<div class="notice">You have no reservations yet. Find your next stay.</div>'};const saved=()=>{panel.innerHTML=favorites.length?`<div class="hotel-list">${favorites.map((h,i)=>`<article class="hotel-card"><img src="${roomPhoto(i)}" alt="Hotel room"><div><p class="tag">${h.city} · ${'★'.repeat(h.rating)}</p><h3>${h.name}</h3><p>${h.address}</p><button data-hotel="${h.id}">View hotel</button></div><aside><button data-remove-favorite="${h.id}">Remove</button></aside></article>`).join('')}</div>`:'<div class="notice">Save places you love and they will appear here.</div>';document.querySelectorAll('[data-hotel]').forEach(b=>b.onclick=()=>location.hash='hotel/'+b.dataset.hotel);document.querySelectorAll('[data-remove-favorite]').forEach(b=>b.onclick=async()=>{await api('/api/favorites/'+b.dataset.removeFavorite,{method:'DELETE'});profile()})};details();document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>({details,trips,favorites:saved})[b.dataset.panel]())}catch(e){if(e.status===401||e.status===403){localStorage.removeItem('vacayToken');refreshAccount();location.hash='login'}else app.innerHTML=`<section class="page"><h2>Could not load your profile</h2><p>${e.message}</p><button data-page="home">Back home</button></section>`;links()}}
async function profile(){if(!localStorage.getItem('vacayToken')){location.hash='login';return}app.innerHTML='<section class="page"><p>Loading your traveller profile…</p></section>';try{const [guest,reservations,favorites,cars]=await Promise.all([api('/api/guests/me'),api('/api/reservations'),api('/api/favorites'),api('/api/car-rentals/mine')]);app.innerHTML=`<section class="page"><p class="tag">Your Vacay account</p><h2>Hi, ${guest.firstName}</h2><div class="profile-tabs"><button data-panel="details">Profile details</button><button data-panel="trips">My stays (${reservations.length})</button><button data-panel="cars">Car rentals (${cars.length})</button><button data-panel="favorites">Saved places (${favorites.length})</button></div><div id="profile-panel"></div></section>`;const panel=document.querySelector('#profile-panel');const details=()=>{panel.innerHTML=`<form class="form-card profile-form" id="profile-form"><h3>Your details</h3><label>First name</label><input name="firstName" value="${guest.firstName}" required><label>Last name</label><input name="lastName" value="${guest.lastName}" required><label>Personal number</label><input name="personalNumber" value="${guest.personalNumber}" required><label>Phone number</label><input name="phoneNumber" value="${guest.phoneNumber}" required><button class="primary">Save changes</button><div id="message"></div></form>`;document.querySelector('#profile-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/guests/me',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});document.querySelector('#message').innerHTML='<div class="notice">Your details were saved.</div>';refreshAccount()}catch(err){formError(err)}}};const trips=()=>{panel.innerHTML=reservations.length?`<div class="trip-list">${reservations.map((r,i)=>{const room=r.reservationRooms[0].room;return `<article class="hotel-card"><img src="${roomPhoto(i)}" alt="${room.name}"><div><p class="tag">Reservation #${r.id}</p><h2>${room.name}</h2><p>${r.checkInDate} → ${r.checkOutDate}</p><p>Breakfast ${i%2?'not included':'included'} · ${22+i} Old Town Street, Tbilisi</p><button data-message-host="${r.id}">Message your host</button><div id="host-${r.id}"></div></div><aside><button class="primary" data-cancel="${r.id}">Cancel reservation</button></aside></article>`}).join('')}</div>`:'<div class="notice">You have no reservations yet. Find your next stay.</div>';document.querySelectorAll('[data-message-host]').forEach(b=>b.onclick=()=>{document.querySelector('#host-'+b.dataset.messageHost).innerHTML='<div class="notice">Host Nino: Hello! I am looking forward to welcoming you. Check-in is from 15:00, and I can recommend cafés, transport, and local places near your stay.</div>'});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{const fee='A 10% cancellation fee applies. Do you accept cancellation?';if(!confirm(fee))return;try{const result=await api('/api/reservations/'+b.dataset.cancel,{method:'DELETE'});alert(`Reservation cancelled. Fee: $${result.fee}. A confirmation email was sent.`);profile()}catch(err){alert(err.message)}})};const carTrips=()=>{panel.innerHTML=cars.length?`<div class="trip-list">${cars.map(c=>`<article class="guide"><h3>${c.car.brand} ${c.car.model}</h3><p>${c.car.city} · ${c.pickupDate} → ${c.dropoffDate}</p><p>${c.pickupLocation} · $${c.car.dailyPrice}/day</p></article>`).join('')}</div>`:'<div class="notice">You have no car rentals yet.</div>'};const saved=()=>{panel.innerHTML=favorites.length?`<div class="hotel-list">${favorites.map((h,i)=>`<article class="hotel-card"><img src="${roomPhoto(i)}" alt="Hotel room"><div><p class="tag">${h.city} · ${'★'.repeat(h.rating)}</p><h3>${h.name}</h3><p>${h.address}</p><button data-hotel="${h.id}">View hotel</button></div><aside><button data-remove-favorite="${h.id}">Remove</button></aside></article>`).join('')}</div>`:'<div class="notice">Save places you love and they will appear here.</div>';document.querySelectorAll('[data-hotel]').forEach(b=>b.onclick=()=>location.hash='hotel/'+b.dataset.hotel);document.querySelectorAll('[data-remove-favorite]').forEach(b=>b.onclick=async()=>{await api('/api/favorites/'+b.dataset.removeFavorite,{method:'DELETE'});profile()})};details();document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>({details,trips,cars:carTrips,favorites:saved})[b.dataset.panel]())}catch(e){if(e.status===401||e.status===403){localStorage.removeItem('vacayToken');refreshAccount();location.hash='login'}else app.innerHTML=`<section class="page"><h2>Could not load your profile</h2><p>${e.message}</p><button data-page="home">Back home</button></section>`;links()}}
// Keep each photo tied to the actual catalog model, instead of assigning
// unrelated stock images by list position.
const carImages={
  'Toyota Yaris':'https://res.cloudinary.com/kbc2ndrb/image/upload/f_auto,q_auto,w_900/2024_Toyota_Yaris_Hybrid_Z.jpg',
  'Hyundai Elantra':'https://res.cloudinary.com/kbc2ndrb/image/upload/f_auto,q_auto,w_900/330px-2023_Hyundai_Elantra_Limited_in_Silver_2C_front_left_2C_04-04-2026.jpg',
  'Kia Sportage':'https://res.cloudinary.com/kbc2ndrb/image/upload/f_auto,q_auto,w_900/2025_Kia_Sportage_S_front_only.jpg',
  'Toyota RAV4':'https://res.cloudinary.com/kbc2ndrb/image/upload/f_auto,q_auto,w_900/2026-toyota-rav4-limited-352-68f0e7f67ae2b.jpg',
  'Mercedes Vito':'https://res.cloudinary.com/kbc2ndrb/image/upload/f_auto,q_auto,w_900/Mercedes-Benz-Vito-Tourer.jpg',
  'Suzuki Jimny':'https://res.cloudinary.com/kbc2ndrb/image/upload/f_auto,q_auto,w_900/LITTLE5.jpg',
  'Volkswagen Golf':'https://res.cloudinary.com/kbc2ndrb/image/upload/f_auto,q_auto,w_900/DB2016AU00877_web_1600.jpg',
  'BMW X3':'https://res.cloudinary.com/kbc2ndrb/image/upload/f_auto,q_auto,w_900/2025-bmw-x3-xdrive30-228-687fec9f6b2e8.jpg',
  'Renault Duster':'https://res.cloudinary.com/kbc2ndrb/image/upload/f_auto,q_auto,w_900/transautomobile-renault-duster-3053-760829.jpg',
  'Ford Transit':'https://res.cloudinary.com/kbc2ndrb/image/upload/f_auto,q_auto,w_900/27_FRD_TRN_PVAN_XLT_55346_v2.webp',
  'Toyota Camry':'https://res.cloudinary.com/kbc2ndrb/image/upload/f_auto,q_auto,w_900/2023_Toyota_Camry_exterior_side_white.png'
};
const carPhoto=(car,index=0)=>{
  const key=`${car?.brand||''} ${car?.model||''}`.trim();
  const source=carImages[key]||carImages[car?.model]||carImages['Toyota Yaris'];
  return source;
};
function cars(){const min=today();app.innerHTML=`<section class="page"><p class="tag">Vacay car rental</p><h1>Drive Georgia your way</h1><p>Choose a city and dates once. Every car includes air conditioning, unlimited kilometres, and pay-at-pick-up booking.</p><form class="booking-bar" id="car-search"><select name="city">${cities.map(c=>`<option>${c}</option>`).join('')}</select><input name="pickupDate" type="date" min="${min}" value="${min}" required><input name="dropoffDate" type="date" min="${min}" required><button class="primary">Find cars</button></form><div id="cars-results" class="hotel-list"></div></section>`;const f=document.querySelector('#car-search');f.dropoffDate.value=new Date(Date.now()+86400000*3).toISOString().slice(0,10);f.onsubmit=async e=>{e.preventDefault();const s=Object.fromEntries(new FormData(f));if(s.dropoffDate<=s.pickupDate){alert('Drop-off must be after pick-up.');return}sessionStorage.setItem('vacayCarSearch',JSON.stringify(s));const box=document.querySelector('#cars-results');box.innerHTML='<p>Loading available cars…</p>';try{const list=await api(`/api/car-rentals/cars?city=${encodeURIComponent(s.city)}&pickupDate=${s.pickupDate}&dropoffDate=${s.dropoffDate}`);box.innerHTML=list.length?list.map((c,i)=>`<article class="hotel-card"><img src="${carPhoto(c,i)}" alt="${c.brand} ${c.model}"><div><p class="tag">${c.city} · ${c.category}</p><h2>${c.brand} ${c.model}</h2><p>${c.year} · ${c.transmission} · ${c.fuel}</p><p>${c.seats} seats · ${c.luggage} bags · Air conditioning · Unlimited kilometres</p></div><aside><small>From</small><strong>$${c.dailyPrice}</strong><small>per day</small><button class="primary" data-rent="${c.id}">Rent this car</button></aside></article>`).join(''):'<div class="notice">No cars are free for those dates. Try different dates.</div>';document.querySelectorAll('[data-rent]').forEach(b=>b.onclick=()=>carCheckout(b.dataset.rent,list.find(c=>c.id===+b.dataset.rent),s))}catch(err){box.innerHTML=`<div class="error">${err.message}. Start Docker again with docker compose up --build, then refresh this page.</div>`}};f.requestSubmit()}
function carCheckout(id,car,s){if(!localStorage.getItem('vacayToken')){sessionStorage.setItem('vacayCarPending',JSON.stringify({id,car,s}));location.hash='login';return}const days=(new Date(s.dropoffDate)-new Date(s.pickupDate))/86400000,base=days*car.dailyPrice,tax=base*.18,total=base+tax;app.innerHTML=`<section class="page narrow"><p class="tag">Complete car rental</p><h2>${car.brand} ${car.model}</h2><form class="form-card" id="car-rental-form"><p>${car.city} · ${s.pickupDate} → ${s.dropoffDate} · ${days} days</p><p>${car.seats} seats · ${car.transmission} · ${car.fuel}</p><label>Driving licence ID</label><input name="drivingLicenseId" required placeholder="Your licence number"><label>Pick-up location</label><select name="pickupLocation"><option>${car.city} city centre</option><option>${car.city} airport</option><option>${car.city} hotel delivery</option></select><p>Rental price: <strong>$${base.toFixed(2)}</strong><br>Taxes (18%): <strong>$${tax.toFixed(2)}</strong><br>Total: <strong>$${total.toFixed(2)}</strong></p><div class="pay-property">Pay at pick-up. Bring your driving licence and confirmation email.</div><button class="primary">Confirm car rental</button><div id="message"></div></form></section>`;document.querySelector('#car-rental-form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));try{const d=await api('/api/car-rentals',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({carId:+id,pickupDate:s.pickupDate,dropoffDate:s.dropoffDate,...values})});app.innerHTML=`<section class="page narrow confirmation"><p class="tag">Car rental confirmed</p><h2>Your drive is booked!</h2><p class="confirmation-icon">✦</p><div class="guide"><p><strong>${car.brand} ${car.model}</strong> in ${car.city}</p><p>${s.pickupDate} → ${s.dropoffDate}</p><p>Booking #${d.id}. We sent your pick-up details to your email.</p></div><button class="primary" data-page="profile">See my profile</button></section>`;links()}catch(err){formError(err)}}}
document.head.insertAdjacentHTML('beforeend','<style>.password-wrap{position:relative}.password-wrap input{padding-right:54px}.eye-toggle{position:absolute;right:8px;top:50%;transform:translateY(-50%);padding:5px 8px;background:transparent;border:0;font-size:18px;cursor:pointer}.password-hint{font-size:13px;margin:5px 0 12px;color:#573c59}</style>');
const passwordInput=()=>`<div class="password-wrap"><input id="password" type="password" name="password" minlength="8" required autocomplete="current-password"><button class="eye-toggle" type="button" aria-label="Show password" title="Show password">◉</button></div>`;
function addPasswordEye(){const input=document.querySelector('#password'),eye=document.querySelector('.eye-toggle');eye.onclick=()=>{const visible=input.type==='text';input.type=visible?'password':'text';eye.textContent=visible?'◉':'◌';eye.title=visible?'Show password':'Hide password'};return input}
function signup(){app.innerHTML=`<section class="page narrow"><p class="tag">Join Vacay</p><h2>Create your account</h2><form class="form-card" id="signup"><label>First name</label><input name="firstName" required><label>Last name</label><input name="lastName" required><label>Personal number</label><input name="personalNumber" inputmode="numeric" required><label>Phone number</label><input name="phoneNumber" type="tel" required><label>Email</label><input type="email" name="email" required><label>Password</label>${passwordInput()}<p class="password-hint">Use at least 8 characters, one uppercase letter, and one symbol, for example: Vacay!2026</p><button class="primary">Create account</button><div id="message"></div></form><p>Already registered? <a href="#login"><u>Log in</u></a></p></section>`;const password=addPasswordEye();document.querySelector('#signup').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(v.password.length<8||!/[A-Z]/.test(v.password)||!/[^A-Za-z0-9]/.test(v.password)){formError(new Error('Password needs 8 characters, one uppercase letter, and one symbol such as ! or @.'));password.focus();return}try{await api('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)});sessionStorage.setItem('vacayEmail',v.email);location.hash='confirm-email'}catch(err){formError(err)}}}
function login(){app.innerHTML=`<section class="page narrow"><p class="tag">Welcome back</p><h2>Log in securely</h2><p>Enter your email and password to access your Vacay profile, reservations, and saved places.</p><form class="form-card" id="login"><label>Email</label><input type="email" name="email" value="${sessionStorage.getItem('vacayEmail')||''}" required><label>Password</label>${passwordInput()}<button class="primary">Log in</button><button type="button" id="forgot-password">Forgot password?</button><div id="message"></div></form><p>New here? <a href="#signup"><u>Create an account</u></a></p></section>`;addPasswordEye();document.querySelector('#login').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));try{const d=await api('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(v)});localStorage.setItem('vacayToken',d.token);sessionStorage.setItem('vacayEmail',v.email);refreshAccount();const roomPending=JSON.parse(sessionStorage.getItem('vacayPendingBooking')||'null'),carPending=JSON.parse(sessionStorage.getItem('vacayCarPending')||'null');if(roomPending)location.hash='checkout';else if(carPending){sessionStorage.removeItem('vacayCarPending');carCheckout(carPending.id,carPending.car,carPending.s)}else location.hash='home'}catch(err){formError(err)}};document.querySelector('#forgot-password').onclick=async()=>{const email=document.querySelector('#login [name=email]').value.trim();if(!email){formError(new Error('Enter your email address first, then press Forgot password.'));return}try{const d=await api('/api/auth/forgot-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,code:''})});document.querySelector('#message').innerHTML=`<div class="notice">${d.message} Check Inbox and Spam, then log in using that new password.</div>`}catch(err){formError(err)}}}
async function profile(){if(!localStorage.getItem('vacayToken')){location.hash='login';return}app.innerHTML='<section class="page"><p>Loading your traveller profile…</p></section>';try{const [guest,reservations,favorites,cars]=await Promise.all([api('/api/guests/me'),api('/api/reservations'),api('/api/favorites'),api('/api/car-rentals/mine')]);const success=sessionStorage.getItem('vacayProfileSuccess')||'';sessionStorage.removeItem('vacayProfileSuccess');app.innerHTML=`<section class="page"><p class="tag">Your Vacay account</p><h2>Hi, ${guest.firstName}</h2>${success?`<div class="notice">${success}</div>`:''}<div class="profile-tabs"><button data-panel="details">Profile details</button><button data-panel="trips">My stays (${reservations.length})</button><button data-panel="cars">Car rentals (${cars.length})</button><button data-panel="favorites">Saved places (${favorites.length})</button></div><div id="profile-panel"></div></section>`;const panel=document.querySelector('#profile-panel');const details=()=>{panel.innerHTML=`<section class="form-card profile-form"><form id="profile-form"><h3>Your details</h3><label>First name</label><input name="firstName" value="${guest.firstName}" required><label>Last name</label><input name="lastName" value="${guest.lastName}" required><label>Personal number</label><input name="personalNumber" value="${guest.personalNumber}" required><label>Phone number</label><input name="phoneNumber" value="${guest.phoneNumber}" required><button class="primary">Save personal details</button></form><hr><form id="password-form"><h3>Change password</h3><label>Current password</label><input type="password" name="currentPassword" required><label>New password</label><input type="password" name="newPassword" minlength="8" required><p class="password-hint">At least 8 characters, one uppercase letter, and one symbol.</p><button class="primary">Save new password</button><div id="message"></div></form></section>`;document.querySelector('#profile-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/guests/me',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});sessionStorage.setItem('vacayProfileSuccess','Your personal details were saved successfully.');profile()}catch(err){formError(err)}};document.querySelector('#password-form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));try{const d=await api('/api/auth/change-password',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});document.querySelector('#message').innerHTML=`<div class="notice">${d.message}</div>`;e.target.reset()}catch(err){formError(err)}}};const trips=()=>{panel.innerHTML=reservations.length?`<div class="trip-list">${reservations.map((r,i)=>{const room=r.reservationRooms[0].room;return `<article class="hotel-card"><img src="${roomPhoto(i)}" alt="${room.name}"><div><p class="tag">Reservation #${r.id}</p><h2>${room.name}</h2><p>${r.checkInDate} → ${r.checkOutDate}</p><p>Breakfast ${i%2?'not included':'included'} · ${22+i} Old Town Street, Tbilisi</p><button data-message-host="${r.id}">Message your host</button><div id="host-${r.id}"></div></div><aside><button class="primary" data-cancel="${r.id}">Cancel reservation</button></aside></article>`}).join('')}</div>`:'<div class="notice">You have no reservations yet. Find your next stay.</div>';document.querySelectorAll('[data-message-host]').forEach(b=>b.onclick=()=>{document.querySelector('#host-'+b.dataset.messageHost).innerHTML='<div class="notice">Host Nino: Hello! I am looking forward to welcoming you. Check-in is from 15:00, and I can recommend cafés, transport, and local places near your stay.</div>'});document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{if(!confirm('A 10% cancellation fee applies. Do you accept cancellation?'))return;try{await api('/api/reservations/'+b.dataset.cancel,{method:'DELETE'});sessionStorage.setItem('vacayProfileSuccess','Reservation successfully cancelled. A confirmation email has been sent.');profile()}catch(err){alert(err.message)}})};const carTrips=()=>{panel.innerHTML=cars.length?`<div class="trip-list">${cars.map(c=>`<article class="guide"><h3>${c.car.brand} ${c.car.model}</h3><p>${c.car.city} · ${c.pickupDate} → ${c.dropoffDate}</p><p>${c.pickupLocation} · $${c.car.dailyPrice}/day</p></article>`).join('')}</div>`:'<div class="notice">You have no car rentals yet.</div>'};const saved=()=>{panel.innerHTML=favorites.length?`<div class="hotel-list">${favorites.map((h,i)=>`<article class="hotel-card"><img src="${roomPhoto(i)}" alt="Hotel room"><div><p class="tag">${h.city} · ${'★'.repeat(h.rating)}</p><h3>${h.name}</h3><p>${h.address}</p><button data-hotel="${h.id}">View hotel</button></div><aside><button data-remove-favorite="${h.id}">Remove</button></aside></article>`).join('')}</div>`:'<div class="notice">Save places you love and they will appear here.</div>';document.querySelectorAll('[data-hotel]').forEach(b=>b.onclick=()=>location.hash='hotel/'+b.dataset.hotel);document.querySelectorAll('[data-remove-favorite]').forEach(b=>b.onclick=async()=>{await api('/api/favorites/'+b.dataset.removeFavorite,{method:'DELETE'});profile()})};details();document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>({details,trips,cars:carTrips,favorites:saved})[b.dataset.panel]())}catch(e){if(e.status===401||e.status===403){localStorage.removeItem('vacayToken');refreshAccount();location.hash='login'}else app.innerHTML=`<section class="page"><h2>Could not load your profile</h2><p>${e.message}</p><button data-page="home">Back home</button></section>`;links()}}
async function profile(){if(!localStorage.getItem('vacayToken')){location.hash='login';return}app.innerHTML='<section class="page"><p>Loading your traveller profile…</p></section>';try{const [guest,reservations,favorites,cars]=await Promise.all([api('/api/guests/me'),api('/api/reservations'),api('/api/favorites'),api('/api/car-rentals/mine')]);const success=sessionStorage.getItem('vacayProfileSuccess')||'';sessionStorage.removeItem('vacayProfileSuccess');app.innerHTML=`<section class="page"><p class="tag">Your Vacay account</p><h2>Hi, ${guest.firstName}</h2>${success?`<div class="notice">${success}</div>`:''}<div class="profile-tabs"><button data-panel="details">Profile details</button><button data-panel="trips">My stays (${reservations.length})</button><button data-panel="cars">Car rentals (${cars.length})</button><button data-panel="favorites">Saved places (${favorites.length})</button></div><div id="profile-panel"></div></section>`;const panel=document.querySelector('#profile-panel');const details=()=>{panel.innerHTML=`<section class="form-card profile-form"><form id="profile-form"><h3>Your details</h3><label>First name</label><input name="firstName" value="${guest.firstName}" required><label>Last name</label><input name="lastName" value="${guest.lastName}" required><label>Personal number</label><input name="personalNumber" value="${guest.personalNumber}" required><label>Phone number</label><input name="phoneNumber" value="${guest.phoneNumber}" required><button class="primary">Save personal details</button></form><hr><form id="password-form"><h3>Change password</h3><label>Current password</label><input type="password" name="currentPassword" required><label>New password</label><input type="password" name="newPassword" minlength="8" required><p class="password-hint">At least 8 characters, one uppercase letter, and one symbol.</p><button class="primary">Save new password</button><div id="message"></div></form></section>`;document.querySelector('#profile-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/guests/me',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});sessionStorage.setItem('vacayProfileSuccess','Your personal details were saved successfully.');profile()}catch(err){formError(err)}};document.querySelector('#password-form').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/auth/change-password',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});document.querySelector('#message').innerHTML=`<div class="notice">${d.message}</div>`;e.target.reset()}catch(err){formError(err)}}};const openChat=async id=>{const reservation=reservations.find(r=>r.id===+id),room=reservation.reservationRooms[0].room;panel.innerHTML=`<section class="host-chat"><button id="back-to-stays">← Back to My stays</button><p class="tag">Reservation #${id}</p><h2>Messages with Host Nino</h2><p class="tiny">About ${room.name}. Ask about check-in, breakfast, transfers, parking, or local recommendations.</p><div class="chat-thread" id="chat-thread"><p>Loading conversation…</p></div><form id="host-chat-form" class="chat-compose"><input name="body" maxlength="800" placeholder="Write a message to Nino…" autocomplete="off" required><button class="primary">Send</button></form><div id="chat-error"></div></section>`;const thread=document.querySelector('#chat-thread'),esc=v=>String(v).replace(/[&<>\"]/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[x]));const render=messages=>{thread.innerHTML=messages.length?messages.map(m=>`<article class="chat-bubble ${m.sender==='Guest'?'guest-message':'host-message'}"><small>${esc(m.sender)} · ${new Date(m.sentAtUtc).toLocaleString()}</small><p>${esc(m.body)}</p></article>`).join(''):'<p class="tiny">Start the conversation with your host.</p>';thread.scrollTop=thread.scrollHeight};const load=async()=>render(await api('/api/reservations/'+id+'/messages'));try{await load()}catch(err){document.querySelector('#chat-error').innerHTML=`<div class="error">${esc(err.message)}</div>`}document.querySelector('#back-to-stays').onclick=trips;document.querySelector('#host-chat-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;try{await api('/api/reservations/'+id+'/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({body:new FormData(form).get('body')})});form.reset();await load()}catch(err){document.querySelector('#chat-error').innerHTML=`<div class="error">${esc(err.message)}</div>`}finally{button.disabled=false}}};const trips=()=>{panel.innerHTML=reservations.length?`<div class="trip-list">${reservations.map((r,i)=>{const room=r.reservationRooms[0].room;return `<article class="hotel-card"><img src="${roomPhoto(i)}" alt="${room.name}"><div><p class="tag">Reservation #${r.id}</p><h2>${room.name}</h2><p>${r.checkInDate} → ${r.checkOutDate}</p><p>Breakfast ${i%2?'not included':'included'} · ${22+i} Old Town Street, Tbilisi</p><button data-message-host="${r.id}">Message your host</button></div><aside><button class="primary" data-cancel="${r.id}">Cancel reservation</button></aside></article>`}).join('')}</div>`:'<div class="notice">You have no reservations yet. Find your next stay.</div>';document.querySelectorAll('[data-message-host]').forEach(b=>b.onclick=()=>openChat(b.dataset.messageHost));document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{if(!confirm('A 10% cancellation fee applies. Do you accept cancellation?'))return;try{await api('/api/reservations/'+b.dataset.cancel,{method:'DELETE'});sessionStorage.setItem('vacayProfileSuccess','Reservation successfully cancelled. A confirmation email has been sent.');profile()}catch(err){alert(err.message)}})};const carTrips=()=>{panel.innerHTML=cars.length?`<div class="trip-list">${cars.map(c=>`<article class="guide"><h3>${c.car.brand} ${c.car.model}</h3><p>${c.car.city} · ${c.pickupDate} → ${c.dropoffDate}</p><p>${c.pickupLocation} · $${c.car.dailyPrice}/day</p></article>`).join('')}</div>`:'<div class="notice">You have no car rentals yet.</div>'};const saved=()=>{panel.innerHTML=favorites.length?`<div class="hotel-list">${favorites.map((h,i)=>`<article class="hotel-card"><img src="${roomPhoto(i)}" alt="Hotel room"><div><p class="tag">${h.city} · ${'★'.repeat(h.rating)}</p><h3>${h.name}</h3><p>${h.address}</p><button data-hotel="${h.id}">View hotel</button></div><aside><button data-remove-favorite="${h.id}">Remove</button></aside></article>`).join('')}</div>`:'<div class="notice">Save places you love and they will appear here.</div>';document.querySelectorAll('[data-hotel]').forEach(b=>b.onclick=()=>location.hash='hotel/'+b.dataset.hotel);document.querySelectorAll('[data-remove-favorite]').forEach(b=>b.onclick=async()=>{await api('/api/favorites/'+b.dataset.removeFavorite,{method:'DELETE'});profile()})};details();document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>({details,trips,cars:carTrips,favorites:saved})[b.dataset.panel]())}catch(e){if(e.status===401||e.status===403){localStorage.removeItem('vacayToken');refreshAccount();location.hash='login'}else app.innerHTML=`<section class="page"><h2>Could not load your profile</h2><p>${e.message}</p><button data-page="home">Back home</button></section>`;links()}}
document.head.insertAdjacentHTML('beforeend','<style>.host-chat{max-width:720px;background:#fffdf9;padding:28px;box-shadow:7px 8px 0 var(--mint)}.chat-thread{height:380px;overflow-y:auto;margin:18px 0;padding:16px;background:#f6eef0;display:flex;flex-direction:column;gap:12px}.chat-bubble{max-width:78%;padding:10px 14px;border-radius:14px}.chat-bubble p{margin:5px 0 0}.chat-bubble small{font-size:11px}.guest-message{align-self:flex-end;background:var(--plum);color:white;border-bottom-right-radius:2px}.guest-message small{color:#f5dce7}.host-message{align-self:flex-start;background:white;border:1px solid #d8cad1;border-bottom-left-radius:2px}.chat-compose{display:grid;grid-template-columns:1fr auto;gap:10px}.chat-compose button{margin:0}.dark .host-chat,.dark .chat-thread{background:#26212a}.dark .host-message{background:#342b38;border-color:#705f6e}.dark .guest-message{background:#7a526f}@media(max-width:600px){.host-chat{padding:17px}.chat-compose{grid-template-columns:1fr}.chat-bubble{max-width:92%}}</style>');
const attractionsByCity={Tbilisi:[['Old Town & Abanotubani','City walks','Explore balconies, courtyards, sulfur-bath domes, and riverside lanes in Tbilisi’s historic centre.',4.8,126,'Free'],['Narikala Fortress','History','Climb above the Old Town for panoramic views and one of the city’s most recognisable landmarks.',4.7,98,8],['Georgian National Museum','Museums','See archaeological treasures, medieval art, and exhibitions that explain Georgia’s long history.',4.6,74,12],['Mtatsminda Park','Family activities','Ride the funicular up Mtatsminda for city views, gentle walks, and family-friendly attractions.',4.5,61,6]],Batumi:[['Batumi Boulevard','Outdoor activities','Walk the palm-lined seafront, sculptures, cafés, and cycle paths beside the Black Sea.',4.8,203,'Free'],['Ali & Nino Statue','Culture','See the moving monument to Ali and Nino beside the harbour and evening promenade.',4.7,114,'Free'],['Batumi Botanical Garden','Nature','Spend a half-day among subtropical plants, sea views, and quiet paths north of the city.',4.8,182,15],['Argo Cable Car','Sightseeing','Glide above Batumi for a wide view of the coastline, port, and city skyline.',4.6,147,13]],Kutaisi:[['Bagrati Cathedral','History','Visit the hilltop cathedral and enjoy a broad view over Kutaisi and the Rioni River.',4.8,144,'Free'],['Gelati Monastery','Culture','Discover medieval architecture and famous frescoes at one of Georgia’s great cultural sites.',4.9,198,10],['Prometheus Cave','Nature','Follow a guided route through illuminated limestone chambers and underground rivers.',4.8,221,18],['Martvili Canyon','Outdoor activities','Take a boat and short walk through turquoise water, waterfalls, and forested cliffs.',4.7,169,20]],Kazbegi:[['Gergeti Trinity Church','History','Reach the iconic church above Stepantsminda for unforgettable mountain views.',4.9,311,'Free'],['Dariali Gorge','Nature','Drive north through a dramatic gorge of cliffs, river views, and mountain air.',4.8,107,'Free'],['Gveleti Waterfalls','Hiking','Take a short mountain walk to twin waterfalls near the Dariali valley.',4.7,82,'Free'],['Truso Valley','Outdoor activities','Spend a full day among mineral springs, villages, and wide high-mountain landscapes.',4.9,66,35]],Telavi:[['Batonistsikhe Fortress','History','Walk through the royal fortress and learn about Kakheti’s kings and vineyards.',4.6,58,5],['Tsinandali Estate','Culture','Tour the historic estate, gardens, and wine cellars associated with Georgian winemaking.',4.8,129,18],['Gremi Monastery','History','See the hilltop church and fortress tower that mark a former Kakhetian capital.',4.7,72,7],['Alaverdi Cathedral','Culture','Visit the monastery and vineyards in the Alazani Valley beneath the Caucasus.',4.8,91,10]],Mestia:[['Svaneti Museum of History and Ethnography','Museums','Learn about Svan traditions, icons, weapons, and life in the high Caucasus.',4.8,84,8],['Mestia Towers','History','Walk among the defensive stone towers that define the town’s unique skyline.',4.9,137,'Free'],['Hatsvali Cable Car','Outdoor activities','Ride above Mestia for mountain panoramas and easy access to alpine walks.',4.8,118,14],['Ushguli Day Trip','Outdoor activities','Travel to one of Europe’s highest inhabited villages and its dramatic valley.',4.9,104,45]],Kobuleti:[['Kobuleti Beach','Outdoor activities','Relax beside the Black Sea on a long pebble beach with cafés close by.',4.6,96,'Free'],['Kobuleti Protected Areas','Nature','Explore wetlands, bird habitats, and quiet trails just outside the resort town.',4.7,44,9],['Petra Fortress','History','See the ruins of a Byzantine-era fortress on a green hill above the coast.',4.7,87,6],['Mtirala National Park','Outdoor activities','Take a day trip into Adjara’s rainforest, waterfalls, and shaded walking routes.',4.9,112,25]]};
