Object.entries(categoryFills).forEach(([city,items])=>attractionsByCity[city].push(...items));
const attractionCategories=['All','Tours','City tours','Museums','Outdoor activities','Food and drinks','History','Culture','Nature','Hiking','Sightseeing','Family activities','City walks'];
const attractionKey=(city,title)=>`${city}:${title}`;
const attractionPhoto=(city,title)=>`https://loremflickr.com/900/600/${encodeURIComponent(`${title},${city}`)}?lock=${Math.abs([...title].reduce((n,c)=>n+c.charCodeAt(0),0))}`;
function attractionCard(city,item){const [title,category,description,rating,reviews,price,image]=item,stored=JSON.parse(localStorage.getItem('vacayAttractions')||'[]'),saved=stored.includes(attractionKey(city,title)),src=image||attractionPhoto(city,title);return `<article class="attraction-card"><img src="${src}" alt="${title}" loading="lazy" onerror="this.onerror=null;this.src='${photoUrl(city,900)}'"><div class="attraction-body"><p class="tag">${category}</p><h3>${title}</h3><p>${description}</p><p class="attraction-rating"><strong>★ ${rating}</strong> · ${reviews} reviews</p><button class="save-attraction" data-attraction="${attractionKey(city,title)}">${saved?'Saved to itinerary':'Save to itinerary'}</button></div><aside><small>From</small><strong>${price==='Free'?'Free':'$'+price}</strong>${price==='Free'?'':'<small>per person</small>'}<button class="primary" data-attraction-view="${title}">View attraction</button></aside></article>`}
function attractions(){const initial=getSearch()?.city||'Tbilisi';app.innerHTML=`<section class="page attractions-page"><p class="tag">Attractions</p><h1>Attractions, activities, and experiences</h1><p class="lead">Discover attractions and experiences for your trip.</p><form class="attraction-search" id="attraction-search"><label>Destination</label><select name="city">${cities.map(c=>`<option ${c===initial?'selected':''}>${c}</option>`).join('')}</select><label>Dates</label><input name="date" type="date" min="${today()}" value="${today()}"><button class="primary">Search</button></form><div class="attraction-categories">${attractionCategories.map(c=>`<button data-attraction-filter="${c}">${c}</button>`).join('')}</div><div id="attraction-results"></div><section class="attraction-benefits"><article><h3>Explore top attractions</h3><p>Find tours, museums, nature, food, and local experiences in every Vacay city.</p></article><article><h3>Fast and flexible</h3><p>Save ideas to your itinerary before you decide what to book.</p></article><article><h3>Local recommendations</h3><p>Every list is written for the cities where Vacay has stays and car rentals.</p></article></section></section>`;const render=(city,filter='All')=>{const list=(attractionsByCity[city]||[]).filter(x=>filter==='All'||x[1]===filter);document.querySelector('#attraction-results').innerHTML=`<div class="topline"><div><p class="tag">Recommended in ${city}</p><h2>Top things to do</h2></div><p>${list.length} experiences</p></div><div class="attraction-list">${list.map(x=>attractionCard(city,x)).join('')}</div>`;document.querySelectorAll('.save-attraction').forEach(button=>button.onclick=()=>{const values=JSON.parse(localStorage.getItem('vacayAttractions')||'[]'),key=button.dataset.attraction,next=values.includes(key)?values.filter(x=>x!==key):[...values,key];localStorage.setItem('vacayAttractions',JSON.stringify(next));button.textContent=next.includes(key)?'Saved to itinerary':'Save to itinerary'});document.querySelectorAll('[data-attraction-view]').forEach(button=>button.onclick=()=>alert(`${button.dataset.attractionView} is available as a local recommendation. Save it to your itinerary, then ask your host for directions.`))};let filter='All';render(initial);document.querySelector('#attraction-search').onsubmit=e=>{e.preventDefault();render(new FormData(e.target).get('city'),filter)};document.querySelectorAll('[data-attraction-filter]').forEach(button=>button.onclick=()=>{filter=button.dataset.attractionFilter;document.querySelectorAll('[data-attraction-filter]').forEach(x=>x.classList.toggle('active',x===button));render(new FormData(document.querySelector('#attraction-search')).get('city'),filter)})}
function route(){const p=location.hash.slice(1)||'home';if(p==='home')home();else if(p==='guides')guides();else if(p==='about')about();else if(p==='stays')stays();else if(p==='cars')cars();else if(p==='attractions')attractions();else if(p==='signup')signup();else if(p==='login')login();else if(p==='profile')profile();else if(p==='checkout')checkout();else if(p==='confirm-email')confirm('email');else if(p==='confirm-login')location.hash='login';else if(p.startsWith('city/'))city(decodeURIComponent(p.slice(5)));else if(p.startsWith('hotel/'))hotel(p.slice(6));else home();setTimeout(localize,0)}window.addEventListener('hashchange',route);addControls();route();refreshAccount();
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-panel="cars"]');if(!tab)return;e.preventDefault();e.stopImmediatePropagation();const panel=document.querySelector('#profile-panel');if(!panel)return;panel.innerHTML='<p>Loading your car rentals…</p>';try{const cars=await api('/api/car-rentals/mine');panel.innerHTML=cars.length?`<div class="trip-list">${cars.map(c=>`<article class="guide car-trip"><h3>${c.car.brand} ${c.car.model}</h3><p>${c.car.city} · ${c.pickupDate} → ${c.dropoffDate}</p><p>${c.pickupLocation} · $${c.car.dailyPrice}/day</p><button class="primary" data-cancel-car="${c.id}">Cancel car rental</button></article>`).join('')}</div>`:'<div class="notice">You have no car rentals yet.</div>'}catch(err){panel.innerHTML=`<div class="error">${err.message}</div>`}},true);
const showCancellation=(kind,result,button)=>{button?.closest('article')?.remove();const emailText=result?.emailSent===false?'The cancellation is complete, but email delivery is temporarily unavailable.':'A cancellation confirmation was sent to the email address on your Vacay account.';const panel=document.querySelector('#profile-panel');if(panel){panel.insertAdjacentHTML('afterbegin',`<div class="notice cancellation-success" role="status"><strong>Cancellation successful.</strong> Your ${kind==='car'?'car rental':'reservation'} has been cancelled. ${emailText}</div>`)}else{app.innerHTML=`<section class="page narrow confirmation"><p class="tag">Cancellation successful</p><h2>Your ${kind==='car'?'car rental':'reservation'} has been cancelled.</h2><p class="confirmation-icon">✓</p><div class="notice">${emailText}</div></section>`}};
document.addEventListener('click',async e=>{const button=e.target.closest('[data-cancel]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();if(!confirm('A 10% cancellation fee applies. Do you accept cancellation?'))return;button.disabled=true;try{const result=await api('/api/reservations/'+button.dataset.cancel,{method:'DELETE'});showCancellation('reservation',result,button)}catch(err){button.disabled=false;document.querySelector('#profile-panel')?.insertAdjacentHTML('afterbegin',`<div class="error">Cancellation could not be completed: ${err.message}</div>`)}},true);
document.addEventListener('click',async e=>{const button=e.target.closest('[data-cancel-car]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();if(!confirm('A 10% cancellation fee applies. Do you accept cancellation?'))return;button.disabled=true;try{const result=await api('/api/car-rentals/'+button.dataset.cancelCar,{method:'DELETE'});showCancellation('car',result,button)}catch(err){button.disabled=false;document.querySelector('#profile-panel')?.insertAdjacentHTML('afterbegin',`<div class="error">Cancellation could not be completed: ${err.message}</div>`)}},true);
window.addEventListener('hashchange',()=>{if(location.hash==='#login'&&localStorage.getItem('vacayToken'))location.hash='profile'});
const renderVacayProfile=profile;profile=async function(panelToOpen){if(panelToOpen)sessionStorage.setItem('vacayProfilePanel',panelToOpen);await renderVacayProfile();const content=app.textContent||'';const hotelCancelled=content.includes('Reservation successfully cancelled'),carCancelled=content.includes('Car rental successfully cancelled');if(hotelCancelled||carCancelled){app.innerHTML=`<section class="page narrow confirmation"><p class="tag">Cancellation successful</p><h2>${hotelCancelled?'Your reservation has been cancelled.':'Your car rental has been cancelled.'}</h2><p class="confirmation-icon">✓</p><div class="notice">Your booking has been removed successfully. A cancellation confirmation was sent to the email address on your Vacay account.</div></section>`;return}const panel=sessionStorage.getItem('vacayProfilePanel');if(!panel)return;sessionStorage.removeItem('vacayProfilePanel');let attempts=0;const openRequestedPanel=()=>{const tab=document.querySelector(`[data-panel="${panel}"]`);if(tab)tab.click();else if(++attempts<12)setTimeout(openRequestedPanel,150)};openRequestedPanel()};
const chat=document.querySelector('#chat'),messages=document.querySelector('#chat-messages');document.querySelector('#chat-toggle').onclick=()=>chat.classList.remove('hidden');document.querySelector('#chat-close').onclick=()=>chat.classList.add('hidden');document.querySelector('#chat-form').onsubmit=async e=>{e.preventDefault();const input=document.querySelector('#chat-input'),q=input.value.trim(),lower=q.toLowerCase();if(!q)return;messages.innerHTML+=`<p><b>You:</b> ${q}</p>`;input.value='';const city=cities.find(c=>lower.includes(c.toLowerCase()))||(getSearch()?.city)||'Tbilisi';let answer=guide[city].intro;if(/cheap|cheapest|lowest|price/.test(lower)){try{const hs=await api('/api/hotels?city='+encodeURIComponent(city));let best=null;for(const h of hs){const s=getSearch(),qs=s?`?checkIn=${s.checkIn}&checkOut=${s.checkOut}`:'';for(const room of await api(`/api/hotels/${h.id}/rooms${qs}`))if((!s||room.capacity>=+s.guests)&&(!best||room.price<best.room.price))best={h,room};}answer=best?`The lowest available option in ${city} is ${best.room.name} at ${best.h.name}: $${best.room.price} per night for up to ${best.room.capacity} guest(s). ${best.room.breakfastIncluded?'Breakfast is included.':'Breakfast is not included.'}`:'I could not find an available room for that search.'}catch{answer='I could not check prices right now. Please try again in a moment.'}}else if(/hotel|room|available|availability/.test(lower))answer=`Search ${city} with your dates and guests above. I will only show rooms available for those exact dates.`;messages.innerHTML+=`<p><b>Vacay:</b> ${answer}</p>`;messages.scrollTop=messages.scrollHeight};
const assistantCity=question=>cities.find(c=>question.includes(c.toLowerCase()))||(getSearch()?.city)||'Tbilisi';
const assistantReply=(en,ka,ru)=>language==='ka'?ka:language==='ru'?ru:en;
async function answerAssistantQuestion(question){
 const q=question.toLowerCase(),city=assistantCity(q),isCar=/\b(car|cars|rental|rent|vehicle|მანქან|авто|машин)/.test(q);
 if(isCar){
  const list=await api('/api/car-rentals/cars?city='+encodeURIComponent(city));
  if(!list.length)return assistantReply(`I could not find cars in ${city} right now.`,`ამჟამად ${city}-ში მანქანა ვერ მოიძებნა.`,`Сейчас в городе ${city} автомобили не найдены.`);
  const cheapest=[...list].sort((a,b)=>a.dailyPrice-b.dailyPrice)[0];
  return assistantReply(`The cheapest car currently listed in ${city} is a ${cheapest.brand} ${cheapest.model} at $${cheapest.dailyPrice} per day. It has ${cheapest.transmission.toLowerCase()} transmission and ${cheapest.seats} seats.`,`ამჟამად ${city}-ში ყველაზე იაფია ${cheapest.brand} ${cheapest.model} — $${cheapest.dailyPrice} დღეში. მანქანას აქვს ${cheapest.transmission.toLowerCase()} გადაცემათა კოლოფი და ${cheapest.seats} ადგილი.`,`Сейчас самый дешёвый автомобиль в городе ${city} — ${cheapest.brand} ${cheapest.model}, $${cheapest.dailyPrice} в день. В нём ${cheapest.transmission.toLowerCase()} коробка передач и ${cheapest.seats} мест.`);
 }
 const wantsRoom=/\b(room|rooms|hotel|hotels|stay|available|availability|ნომერ|სასტუმრ|ოთახ|номер|отел)/.test(q);
 if(wantsRoom){
  const search=getSearch()||{};
  const tonight=/\btonight|this evening|დღეს|сегодня/.test(q);
  const checkIn=tonight?today():(search.checkIn||today());
  const checkOut=tonight?new Date(Date.now()+86400000).toISOString().slice(0,10):(search.checkOut||new Date(Date.now()+86400000).toISOString().slice(0,10));
  const guests=+(search.guests||q.match(/(\d+)\s*(?:guest|person|სტუმარ|гост)/)?.[1]||1);
  const budgetMatch=q.match(/(?:under|below|up to|max(?:imum)?|less than|under)\s*\$?\s*(\d+)/);
  const budget=budgetMatch?+budgetMatch[1]:null;
  const hotels=await api('/api/hotels?city='+encodeURIComponent(city));
  const matches=(await Promise.all(hotels.map(async h=>({h,rooms:await api(`/api/hotels/${h.id}/rooms?checkIn=${checkIn}&checkOut=${checkOut}`)})))).flatMap(x=>x.rooms.filter(r=>r.capacity>=guests&&(!budget||r.price<=budget)).map(room=>({h:x.h,room})));
  const best=matches.sort((a,b)=>a.room.price-b.room.price)[0];
  if(best)return assistantReply(`For ${city} tonight, the best available match is ${best.room.name} at ${best.h.name}: $${best.room.price} per night${best.room.breakfastIncluded?', breakfast included':''}.`,`დღეს ღამით ${city}-ში საუკეთესო ხელმისაწვდომი ვარიანტია ${best.room.name}, სასტუმრო ${best.h.name}-ში: $${best.room.price} ღამეში${best.room.breakfastIncluded?', საუზმე შედის':''}.`,`Сегодня ночью в городе ${city} лучший доступный вариант — ${best.room.name} в отеле ${best.h.name}: $${best.room.price} за ночь${best.room.breakfastIncluded?', завтрак включён':''}.`);
  return assistantReply(`I could not find an available room in ${city} for those dates${budget?' within your price limit':''}. Try a different date or budget.`,`ამ თარიღებისთვის ${city}-ში ხელმისაწვდომი ნომერი${budget?' თქვენს ბიუჯეტში':''} ვერ მოიძებნა. სცადეთ სხვა თარიღი ან ბიუჯეტი.`,`На эти даты в городе ${city} не найден доступный номер${budget?' в вашем бюджете':''}. Попробуйте изменить даты или бюджет.`);
 }
 return guide[city].intro;
}
document.addEventListener('submit',async e=>{if(e.target.id!=='chat-form')return;e.preventDefault();e.stopImmediatePropagation();const input=document.querySelector('#chat-input'),chatMessages=document.querySelector('#chat-messages'),question=input.value.trim();if(!question)return;chatMessages.innerHTML+=`<p><b>You:</b> ${question}</p>`;input.value='';chatMessages.innerHTML+='<p><b>Vacay:</b> Checking live availability…</p>';try{const answer=await answerAssistantQuestion(question);const pending=chatMessages.querySelector('p:last-child');if(pending)pending.innerHTML=`<b>Vacay:</b> ${answer}`;else chatMessages.innerHTML+=`<p><b>Vacay:</b> ${answer}</p>`}catch(err){const pending=chatMessages.querySelector('p:last-child');if(pending)pending.innerHTML=`<b>Vacay:</b> ${err.message||'I could not check live availability right now.'}`}chatMessages.scrollTop=chatMessages.scrollHeight},true);
